const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

if (data.length > 0) {
    const T = data[0];
    const N = data[1];
    const X = data.slice(2, 2 + N).sort((a, b) => a - b);

    let ans = Infinity;

    ans = Math.min(ans, (X[0] + X[1]) / 2);
    ans = Math.min(ans, T - (X[N - 2] + X[N - 1]) / 2);

    for (let i = 1; i < N - 1; i++) {
        ans = Math.min(ans, (X[i + 1] - X[i - 1]) / 2);
    }

    console.log(ans.toFixed(2));
}
